class ChainHashMap:
    def __init__(self, cap=11):
        self._table = [None] * cap
        self._n = 0

    def _bucket(self, k):
        return k % len(self._table)

    def _resize(self, cap):
        old = self._table
        self._table = [None] * cap
        self._n = 0
        for bucket in old:
            if bucket:
                for k, v in bucket:
                    self.put(k, v)

    def put(self, k, v):
        j = self._bucket(k)
        if self._table[j] is None:
            self._table[j] = []
        for item in self._table[j]:
            if item[0] == k:
                item[1] = v
                return
        self._table[j].append([k, v])
        self._n += 1
        if self._n > len(self._table) // 2:
            self._resize(2 * len(self._table) - 1)

    def get(self, k):
        bucket = self._table[self._bucket(k)]
        if bucket:
            for item in bucket:
                if item[0] == k:
                    return item[1]
        return -1

    def remove(self, k):
        bucket = self._table[self._bucket(k)]
        if bucket:
            for i, item in enumerate(bucket):
                if item[0] == k:
                    bucket.pop(i)
                    self._n -= 1
                    return True
        return False

    def size(self):
        return self._n

