class _Node:
    __slots__ = "key", "left", "right"
    def __init__(self, key):
        self.key, self.left, self.right = key, None, None


class BST:
    def __init__(self):
        self._root = None
        self._size = 0

    def insert(self, k):
        if self._root is None:
            self._root = _Node(k)
            self._size = 1
            return True
        p = self._root
        while True:
            if k == p.key:
                return False
            if k < p.key:
                if p.left is None:
                    p.left = _Node(k)
                    break
                p = p.left
            else:
                if p.right is None:
                    p.right = _Node(k)
                    break
                p = p.right
        self._size += 1
        return True

    def contains(self, k):
        p = self._root
        while p is not None:
            if k == p.key:
                return True
            p = p.left if k < p.key else p.right
        return False

    def delete(self, k):
        parent, p = None, self._root
        while p is not None and p.key != k:
            parent, p = p, (p.left if k < p.key else p.right)
        if p is None:
            return False
        if p.left is not None and p.right is not None:
            rp, r = p, p.left
            while r.right is not None:
                rp, r = r, r.right
            p.key = r.key
            parent, p = rp, r
        child = p.left if p.left is not None else p.right
        if parent is None:
            self._root = child
        elif parent.left is p:
            parent.left = child
        else:
            parent.right = child
        self._size -= 1
        return True

    def min(self):
        p = self._root
        if p is None:
            return None
        while p.left is not None:
            p = p.left
        return p.key

    def max(self):
        p = self._root
        if p is None:
            return None
        while p.right is not None:
            p = p.right
        return p.key

    def floor(self, k):
        best, p = None, self._root
        while p is not None:
            if p.key == k:
                return k
            if p.key < k:
                best = p.key
                p = p.right
            else:
                p = p.left
        return best

    def inorder(self):
        out, stack, p = [], [], self._root
        while stack or p is not None:
            while p is not None:
                stack.append(p)
                p = p.left
            p = stack.pop()
            out.append(p.key)
            p = p.right
        return out

    def size(self):
        return self._size

