class Solution:
    def is_avl(self, root):
        ok = True

        def rec(p, lo, hi):
            nonlocal ok
            if p is None or not ok:
                return 0
            if (lo is not None and p.val <= lo) or (hi is not None and p.val >= hi):
                ok = False
                return 0
            hl = rec(p.left, lo, p.val)
            hr = rec(p.right, p.val, hi)
            if abs(hl - hr) > 1:
                ok = False
            return 1 + max(hl, hr)

        rec(root, None, None)
        return ok

