class Solution:
    def avl_insert(self, keys):
        def h(n):
            return n.height if n else 0

        def fix(n):
            n.height = 1 + max(h(n.left), h(n.right))

        def rot_right(y):
            x = y.left
            y.left, x.right = x.right, y
            fix(y); fix(x)
            return x

        def rot_left(x):
            y = x.right
            x.right, y.left = y.left, x
            fix(x); fix(y)
            return y

        def insert(n, k):
            if n is None:
                t = TreeNode(k)
                t.height = 1
                return t
            if k < n.val:
                n.left = insert(n.left, k)
            elif k > n.val:
                n.right = insert(n.right, k)
            else:
                return n
            fix(n)
            bal = h(n.left) - h(n.right)
            if bal > 1:
                if h(n.left.left) < h(n.left.right):
                    n.left = rot_left(n.left)
                return rot_right(n)
            if bal < -1:
                if h(n.right.right) < h(n.right.left):
                    n.right = rot_right(n.right)
                return rot_left(n)
            return n

        root = None
        for k in keys:
            root = insert(root, k)
        return root

