def merge_sort_count(A):
    def rec(S):
        if len(S) < 2:
            return list(S), 0
        mid = len(S) // 2
        L, a = rec(S[:mid])
        R, b = rec(S[mid:])
        out, i, j, inv = [], 0, 0, a + b
        while i < len(L) and j < len(R):
            if L[i] <= R[j]:
                out.append(L[i]); i += 1
            else:
                out.append(R[j]); j += 1
                inv += len(L) - i
        out.extend(L[i:]); out.extend(R[j:])
        return out, inv
    s, inv = rec(A)
    return [s, inv]

