import random


def quick_sort(S):
    def sort(a, b):
        while a < b:
            p = S[random.randint(a, b)]
            lt, i, gt = a, a, b
            while i <= gt:
                if S[i] < p:
                    S[lt], S[i] = S[i], S[lt]
                    lt += 1
                    i += 1
                elif S[i] > p:
                    S[i], S[gt] = S[gt], S[i]
                    gt -= 1
                else:
                    i += 1
            if lt - a < b - gt:
                sort(a, lt - 1)
                a = gt + 1
            else:
                sort(gt + 1, b)
                b = lt - 1
    sort(0, len(S) - 1)

