    fail = [0] * m
    k = 0
    for j in range(1, m):
        while k > 0 and P[j] != P[k]:
            k = fail[k - 1]
        if P[j] == P[k]:
            k += 1
        fail[j] = k
    out = []
    k = 0
    for j, c in enumerate(T):
        while k > 0 and c != P[k]:
            k = fail[k - 1]
        if c == P[k]:
            k += 1
        if k == m:
            out.append(j - m + 1)
            k = fail[k - 1]
    return out

