def lcs(X, Y):
    n, m = len(X), len(Y)
    L = [[0] * (m + 1) for _ in range(n + 1)]
    for j in range(n):
        row, nxt = L[j], L[j + 1]
        xj = X[j]
        for k in range(m):
            if xj == Y[k]:
                nxt[k + 1] = row[k] + 1
            else:
                a, b = row[k + 1], nxt[k]
                nxt[k + 1] = a if a >= b else b
    out = []
    j, k = n, m
    while L[j][k] > 0:
        if X[j - 1] == Y[k - 1]:
            out.append(X[j - 1])
            j -= 1
            k -= 1
        elif L[j - 1][k] >= L[j][k - 1]:
            j -= 1
