def mst_weight(n, edges):
    parent = list(range(n))
    size = [1] * n

    def find(p):
        root = p
        while parent[root] != root:
            root = parent[root]
        while parent[p] != root:
            parent[p], p = root, parent[p]
        return root

    total, used = 0, 0
    for w, u, v in sorted((w, u, v) for u, v, w in edges):
        a, b = find(u), find(v)
        if a != b:
            if size[a] < size[b]:
                a, b = b, a
            parent[b] = a
            size[a] += size[b]
            total += w
            used += 1
            if used == n - 1:
                break
    return total if used == n - 1 else -1

