def to_postfix(expr):
    prec = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}
    out, ops = [], []
    i, n = 0, len(expr)
    while i < n:
        ch = expr[i]
        if ch == " ":
            i += 1
            continue
        if ch.isdigit():                       # a whole run of digits is one number
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            out.append(expr[i:j])
            i = j
            continue
        if ch.isalpha():
            out.append(ch)
        elif ch == "(":
            ops.append(ch)
        elif ch == ")":
            while ops[-1] != "(":
                out.append(ops.pop())
            ops.pop()
        else:
            while ops and ops[-1] != "(" and (
                    prec[ops[-1]] > prec[ch] or (prec[ops[-1]] == prec[ch] and ch != "^")):
                out.append(ops.pop())
            ops.append(ch)
        i += 1
    while ops:
        out.append(ops.pop())
    return " ".join(out)

