class AdaptablePQ:
    def __init__(self):
        self._heap = []          # entries [key, loc, value, index], in heap order
        self._where = {}         # loc -> entry, for entries still in the queue
        self._next = 1

    def _less(self, i, j):
        a, b = self._heap[i], self._heap[j]
        return (a[0], a[1]) < (b[0], b[1])       # key first, then locator

    def _swap(self, i, j):
        h = self._heap
        h[i], h[j] = h[j], h[i]
        h[i][3], h[j][3] = i, j                  # entries always know their index

    def _upheap(self, j):
        while j > 0 and self._less(j, (j - 1) // 2):
            self._swap(j, (j - 1) // 2)
            j = (j - 1) // 2

    def _downheap(self, j):
        n = len(self._heap)
        while 2 * j + 1 < n:
            c = 2 * j + 1
            if c + 1 < n and self._less(c + 1, c):
                c += 1
            if self._less(c, j):
                self._swap(j, c)
                j = c
            else:
                break

    def _bubble(self, j):
        if j > 0 and self._less(j, (j - 1) // 2):
            self._upheap(j)
        else:
            self._downheap(j)

    def add(self, k, v):
        loc = self._next
        self._next += 1
        entry = [k, loc, v, len(self._heap)]
        self._heap.append(entry)
        self._where[loc] = entry
        self._upheap(len(self._heap) - 1)
        return loc

    def min(self):
        if not self._heap:
            return None
        e = self._heap[0]
        return [e[0], e[2]]

    def remove_min(self):
        if not self._heap:
            return None
        return self.remove(self._heap[0][1])

    def update(self, loc, k, v):
        e = self._where.get(loc)
        if e is None:
            return False
        e[0], e[2] = k, v
        self._bubble(e[3])
        return True

    def remove(self, loc):
        e = self._where.pop(loc, None)
        if e is None:
            return None
        j, last = e[3], len(self._heap) - 1
        if j != last:
            self._swap(j, last)
        self._heap.pop()
        if j < len(self._heap):
            self._bubble(j)
        return [e[0], e[2]]

    def size(self):
        return len(self._heap)

