_DELETED = object()        # deletion marker (tombstone)


class ProbingMap:
    def __init__(self, N):
        self._table = [None] * N      # None, _DELETED, or [key, value]
        self._n = 0

    def _find(self, k):
        """(True, j) if k is in cell j; else (False, first reusable cell or -1)."""
        N = len(self._table)
        j = k % N
        free = -1
        for _ in range(N):            # never examine more than N cells
            cell = self._table[j]
            if cell is None:
                return False, (j if free == -1 else free)
            if cell is _DELETED:
                if free == -1:
                    free = j
            elif cell[0] == k:
                return True, j
            j = (j + 1) % N
        return False, free

    def put(self, k, v):
        found, j = self._find(k)
        if found:
            self._table[j][1] = v
        elif j != -1:
            self._table[j] = [k, v]
            self._n += 1
        return j

    def get(self, k):
        found, j = self._find(k)
        return self._table[j][1] if found else -1

    def remove(self, k):
        found, j = self._find(k)
        if found:
            self._table[j] = _DELETED
            self._n -= 1
        return found

    def size(self):
        return self._n

    def cells(self):
        return [None if c is None else "X" if c is _DELETED else c[0] for c in self._table]

